def _voz(freq, harm=(1, 0, .33, 0, .2), dur=0.05, ruido=0.0):
    def f(s):
        s.tom(0, dur, freq, 0.55, harm=harm, ataque=0.002, decai=dur * 0.45, liberar=0.01)
        if ruido:
            s.ruido(0, dur, ruido, corte=0.4, ataque=0.001, decai=dur * 0.3)
    return f

