    def f(s):
        s.ruido(0, 0.03, 0.7, corte=0.75, decai=0.004, passa_alta=True)
        s.tom(0, 0.05, 150 * fator, 0.4, ataque=0.001, decai=0.012)
        s.tom(0.004, 0.04, 2300 * fator, 0.08, ataque=0.001, decai=0.008)
    return f

